"""Controller-driven network checks for dragging and interruptible finishers."""
import json,time,math
from pathlib import Path
from run_acceptance import *
results=[]
def test(name,predicate,seconds=12):
 d=wait_for(predicate,seconds);results.append({'name':name,'passed':True,'observed':d});Path('Saved/EquipmentQA/finishers.json').write_text(json.dumps(results,indent=2));print('PASS',name,flush=True);return d
def paired(d):return synced(d,2,lambda p:p['captor']) and synced(d,1,lambda p:p['restrained'])
def clear(d):return synced(d,2,lambda p:not p['restrained']) and synced(d,1,lambda p:not p['restrained'])
def grab():
 action(0,'takedown_rear');time.sleep(.6);pad(2,'x');test('X establishes live rear hold',paired)
def release():pad(2,'b');test('B releases both participants',clear)
def hold_rt():action(2,'pad_rt_down');time.sleep(.75);action(2,'pad_rt_up')
def recovered():test('merc respawns with fresh grenade supply',lambda d:synced(d,1,lambda p:p['health']==100 and p['mercGrenades']==2),15)
def owned(d,index):
 identity=player(d,index)['playerId'];return next(p for w in d['worlds'] for p in w['pawns'] if p['local'] and p['playerId']==identity)
try:
 stop();call(project_tool,'open_map',map_name='Prototype');start(4)
 test('all four clients load eight original paired animation clips',lambda d:len(d['worlds'])==4 and all(len(w['pawns'])==4 and all(p['grabClipCount']==8 for p in w['pawns']) for w in d['worlds']),25)
 grab();before=player(report(),2)
 action(2,'pad_move_down');time.sleep(.8);action(2,'pad_move_up');time.sleep(.35)
 test('captor drags merc slowly with replicated alignment',lambda d:paired(d) and 15<math.dist([player(d,2)[k] for k in ['x','y']],[before[k] for k in ['x','y']])<135 and aligned(d,1) and aligned(d,2) and player(d,2)['maxSpeed']==85)
 before=player(report(),2)['yaw'];action(2,'pad_look_down');time.sleep(.65);action(2,'pad_look_up');time.sleep(.4)
 test('turning rotates held merc on all clients',lambda d:paired(d) and abs(player(d,2)['yaw']-before)>30 and synced(d,1,lambda p:abs(p['yaw']-player(d,2)['yaw'])<8))
 release();grab();pad(2,'rt')
 test('tap RT starts synchronized neck snap before applying damage',lambda d:synced(d,2,lambda p:p['finisher']==1) and synced(d,1,lambda p:p['finisher']==1 and p['health']==100),3)
 test('neck snap kills exactly the held merc and closes pair',lambda d:clear(d) and synced(d,1,lambda p:p['health']==0) and synced(d,2,lambda p:p['health']==100))
 recovered();grab();action(1,'grenades_empty');hold_rt()
 test('hold RT selects kick when merc has no grenades',lambda d:synced(d,2,lambda p:p['finisher']==2) and synced(d,1,lambda p:p['health']==100 and p['mercGrenades']==0),3)
 test('kick sequence keeps both committed and voice pair open',lambda d:paired(d) and owned(d,2)['voice']['desiredChannel']=='Grab' and player(d,2)['maxSpeed']==0)
 test('authored kick reaches the kneeling mercs head near impact',lambda d:2.65<player(d,2)['finishElapsed']<3.08 and player(d,2).get('kickContactDistance',999)<35,5)
 test('kick finisher kills merc after the longer sequence',lambda d:clear(d) and synced(d,1,lambda p:p['health']==0))
 recovered();grab();hold_rt()
 test('hold RT chooses grenade while merc has ammunition',lambda d:synced(d,2,lambda p:p['finisher']==3),3)
 test('armed grenade consumes one actual merc grenade',lambda d:all(w['armedGrenades']==1 for w in d['worlds']) and synced(d,1,lambda p:p['mercGrenades']==1 and p['health']==100))
 test('grenade detonates and merc dies while spy survives shove distance',lambda d:clear(d) and synced(d,1,lambda p:p['health']==0) and synced(d,2,lambda p:p['health']==100),10)
 recovered();grab();action(1,'grenades_empty');hold_rt();action(2,'wound')
 test('third-party damage interrupts the kick finisher',lambda d:clear(d) and synced(d,2,lambda p:p['health']==90) and synced(d,1,lambda p:p['health']==100))
 time.sleep(3.5);test('interrupted kick never applies a delayed kill',lambda d:synced(d,1,lambda p:p['health']==100))
 grab();action(1,'grenades_full');hold_rt()
 test('grenade is armed before interruption test',lambda d:server(d)['armedGrenades']==1 and player(d,1)['mercGrenades']==1)
 action(2,'wound');test('damage breaks grenade animation and voice immediately',lambda d:clear(d) and owned(d,2)['voice']['pairToken']==0)
 test('pulled-pin grenade survives the interrupted animation then explodes',lambda d:all(w['armedGrenades']==0 for w in d['worlds']) and (player(d,1)['health']<100 or player(d,2)['health']<80),8)
 test('both players recover after interruption blast',lambda d:all(player(d,i)['health']>0 for i in [1,2]),15)
 action(0,'network_lag');grab();action(1,'grenades_empty');hold_rt()
 test('extended finisher and death converge under 100ms lag and 2 percent loss',lambda d:clear(d) and synced(d,1,lambda p:p['health']==0),15)
 action(0,'network_reset');recovered()
 action(0,'takedown_wall');time.sleep(.6);pad(2,'x');test('rear hold established next to solid partition',paired)
 action(2,'pad_move_down');time.sleep(1.);action(2,'pad_move_up');time.sleep(.5)
 test('drag stops both capsules before wall without crossing or desynchronizing',lambda d:paired(d) and player(d,1)['x']<-72 and player(d,2)['x']<-130 and aligned(d,1) and aligned(d,2))
 hold_rt();time.sleep(.3);test('extended shove rejected when corridor blocked and ammunition preserved',lambda d:paired(d) and synced(d,2,lambda p:p['finisher']==0) and synced(d,1,lambda p:p['mercGrenades']==2 and p['health']==100))
 release();grab();action(1,'grenades_empty');action(0,'grab_observer');hold_rt()
 for _ in range(3):pad(3,'rt');time.sleep(.23)
 test('other merc can shoot spy dead during longer finisher and save partner',lambda d:clear(d) and synced(d,2,lambda p:p['health']==0) and synced(d,1,lambda p:p['health']==100))
 test('spy respawns after rescue gunfire',lambda d:synced(d,2,lambda p:p['health']==100),15)
 grab();action(2,'pad_rt_down');action(1,'damage');action(2,'pad_rt_up')
 test('victim death cancels pending trigger-hold intent',lambda d:clear(d) and synced(d,1,lambda p:p['health']==0))
 recovered();grab();time.sleep(.8)
 test('new grab never inherits previous trigger hold or delayed finisher',lambda d:paired(d) and synced(d,2,lambda p:p['finisher']==0) and synced(d,1,lambda p:p['health']==100))
 release();grab();hold_rt();action(0,'expire')
 test('round end cancels finisher and all voice links',lambda d:clear(d) and all(owned(d,i)['voice']['pairToken']==0 for i in [1,2]))
 print(json.dumps({'passed':len(results),'total':len(results)}),flush=True)
finally:
 stop();start(1);action(0,'automation_off')
